import hmac
import hashlib
import os
import secrets
import sqlite3
import struct
from flask import Flask, request, jsonify, g
from functools import wraps
import argon2

app = Flask(__name__)
app.config['SECRET_KEY'] = secrets.token_hex(32)

SHARED_BUFFER_SIZE = 4096
MAX_CHUNK_SIZE = 1024
API_SECRET = os.environ.get('API_SECRET', secrets.token_hex(32))

# Argon2 password hasher
ph = argon2.PasswordHasher(time_cost=3, memory_cost=65536, parallelism=4)

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(':memory:')
        g.db.row_factory = sqlite3.Row
        _init_db(g.db)
    return g.db

def _init_db(db):
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        user_id INTEGER,
        action TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    try:
        db.execute("INSERT INTO users (username, password_hash, role) VALUES (?, ?, ?)",
                   ('admin', ph.hash('Adm1n$ecureP@ss!'), 'admin'))
        db.execute("INSERT INTO users (username, password_hash, role) VALUES (?, ?, ?)",
                   ('operator', ph.hash('0per@t0rP@ss!'), 'operator'))
        db.commit()
    except sqlite3.IntegrityError:
        pass

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing authorization'}), 401
        token = auth_header[7:]
        parts = token.split('.')
        if len(parts) != 3:
            return jsonify({'error': 'Invalid token format'}), 401
        try:
            user_id = int(parts[0])
            timestamp = int(parts[1])
            provided_mac = parts[2]
        except (ValueError, IndexError):
            return jsonify({'error': 'Invalid token'}), 401
        msg = f"{user_id}.{timestamp}".encode()
        expected_mac = hmac.new(API_SECRET.encode(), msg, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(provided_mac, expected_mac):
            return jsonify({'error': 'Invalid token'}), 401
        import time
        if time.time() - timestamp > 3600:
            return jsonify({'error': 'Token expired'}), 401
        db = get_db()
        user = db.execute('SELECT * FROM users WHERE id = ?', (user_id,)).fetchone()
        if not user:
            return jsonify({'error': 'User not found'}), 401
        g.current_user = dict(user)
        return f(*args, **kwargs)
    return decorated

def require_role(role):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            if g.current_user.get('role') != role:
                return jsonify({'error': 'Insufficient privileges'}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator

class SecureBuffer:
    """Managed shared memory buffer with bounds checking for IPC data exchange."""

    def __init__(self, size):
        self.size = size
        self._buffer = bytearray(size)
        self._lock = False
        self._owner = None

    def _check_bounds(self, offset, length):
        """Validate that offset and length are within buffer bounds.

        Both offset and length are validated as non-negative integers.
        Offset is validated first, then remaining space is checked.
        """
        if not isinstance(offset, int) or not isinstance(length, int):
            raise TypeError("Offset and length must be integers")
        if offset < 0 or length < 0:
            raise ValueError("Offset and length must be non-negative")
        if length > MAX_CHUNK_SIZE:
            raise ValueError(f"Chunk size exceeds maximum ({MAX_CHUNK_SIZE})")
        if offset >= self.size:
            raise OverflowError("Offset exceeds buffer bounds")
        # Safe bounds check: compute remaining space from validated offset
        if length > self.size - offset:
            raise OverflowError("Access would exceed buffer bounds")
        return True

    def write(self, offset, data, user_id):
        """Write data to buffer at specified offset with bounds checking."""
        length = len(data)
        self._check_bounds(offset, length)
        if self._lock and self._owner != user_id:
            raise PermissionError("Buffer is locked by another user")
        self._buffer[offset:offset + length] = data
        return length

    def read(self, offset, length, user_id):
        """Read data from buffer at specified offset with bounds checking."""
        self._check_bounds(offset, length)
        if self._lock and self._owner != user_id:
            raise PermissionError("Buffer is locked by another user")
        return bytes(self._buffer[offset:offset + length])

    def acquire_lock(self, user_id):
        if self._lock and self._owner != user_id:
            return False
        self._lock = True
        self._owner = user_id
        return True

    def release_lock(self, user_id):
        if self._owner == user_id:
            self._lock = False
            self._owner = None
            return True
        return False

# Global shared buffer instance
shared_buffer = SecureBuffer(SHARED_BUFFER_SIZE)

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing credentials'}), 400
    username = data['username']
    password = data['password']
    if not isinstance(username, str) or not isinstance(password, str):
        return jsonify({'error': 'Invalid input types'}), 400
    if len(username) > 64 or len(password) > 128:
        return jsonify({'error': 'Input too long'}), 400
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE username = ?', (username,)).fetchone()
    if not user:
        try:
            ph.verify(ph.hash('dummy_password_constant'), password)
        except Exception:
            pass
        return jsonify({'error': 'Invalid credentials'}), 401
    try:
        ph.verify(user['password_hash'], password)
    except argon2.exceptions.VerifyMismatchError:
        return jsonify({'error': 'Invalid credentials'}), 401
    except argon2.exceptions.VerificationError:
        return jsonify({'error': 'Invalid credentials'}), 401
    import time
    timestamp = int(time.time())
    msg = f"{user['id']}.{timestamp}".encode()
    mac = hmac.new(API_SECRET.encode(), msg, hashlib.sha256).hexdigest()
    token = f"{user['id']}.{timestamp}.{mac}"
    db.execute('INSERT INTO audit_log (user_id, action) VALUES (?, ?)',
               (user['id'], 'login'))
    db.commit()
    return jsonify({'token': token, 'role': user['role']})

@app.route('/api/buffer/write', methods=['POST'])
@require_auth
def buffer_write():
    """Write data to the shared buffer. Requires authentication."""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Missing request body'}), 400

    offset = data.get('offset')
    payload = data.get('data')

    if offset is None or payload is None:
        return jsonify({'error': 'Missing offset or data'}), 400

    if not isinstance(offset, int):
        return jsonify({'error': 'Offset must be an integer'}), 400

    if not isinstance(payload, str):
        return jsonify({'error': 'Data must be a string'}), 400

    try:
        raw_data = bytes.fromhex(payload)
    except ValueError:
        return jsonify({'error': 'Data must be valid hex'}), 400

    user_id = g.current_user['id']

    try:
        written = shared_buffer.write(offset, raw_data, user_id)
        db = get_db()
        db.execute('INSERT INTO audit_log (user_id, action) VALUES (?, ?)',
                   (user_id, f'buffer_write:offset={offset},len={len(raw_data)}'))
        db.commit()
        return jsonify({'written': written, 'offset': offset})
    except (OverflowError, ValueError, TypeError) as e:
        return jsonify({'error': str(e)}), 400
    except PermissionError as e:
        return jsonify({'error': str(e)}), 423

@app.route('/api/buffer/read', methods=['GET'])
@require_auth
def buffer_read():
    """Read data from the shared buffer. Requires authentication."""
    offset = request.args.get('offset', type=int)
    length = request.args.get('length', type=int)

    if offset is None or length is None:
        return jsonify({'error': 'Missing offset or length'}), 400

    user_id = g.current_user['id']

    try:
        result = shared_buffer.read(offset, length, user_id)
        return jsonify({'data': result.hex(), 'offset': offset, 'length': length})
    except (OverflowError, ValueError, TypeError) as e:
        return jsonify({'error': str(e)}), 400
    except PermissionError as e:
        return jsonify({'error': str(e)}), 423

@app.route('/api/buffer/lock', methods=['POST'])
@require_auth
@require_role('admin')
def buffer_lock():
    """Acquire exclusive lock on the buffer. Admin only."""
    user_id = g.current_user['id']
    if shared_buffer.acquire_lock(user_id):
        return jsonify({'status': 'locked', 'owner': user_id})
    return jsonify({'error': 'Buffer already locked'}), 409

@app.route('/api/buffer/unlock', methods=['POST'])
@require_auth
@require_role('admin')
def buffer_unlock():
    """Release buffer lock. Admin only."""
    user_id = g.current_user['id']
    if shared_buffer.release_lock(user_id):
        return jsonify({'status': 'unlocked'})
    return jsonify({'error': 'Not lock owner'}), 403

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000, debug=False)
